import type * as Phaser from 'phaser';
import { t } from '../../i18n';
import { getOverlayRoot } from '../fullscreen';
import { appendForestDialogClose, applyForestDialogTheme } from '../ForestModal';
import { activateUi } from '../UiAudio';
import {
  CREDITS_DEVELOPER,
  CREDITS_FONTS,
  CREDITS_TOOLS,
  PRIVACY_URL,
  THIRD_PARTY_NOTICES_URL,
  type CreditsEntry,
} from './creditsContent';
import { SOUND_CREDITS } from './soundCredits';
import '../ProfileDialog.css';
import './CreditsDialog.css';

/** Design size of the wooden frame; the CSS clamps the dialog to the viewport. */
const FRAME_W = 760;
const FRAME_H = 820;

/** Captured DOM events must not reach Phaser or game hotkeys while the native modal is open. */
const ISOLATED_EVENTS = ['pointerdown', 'pointerup', 'pointermove', 'mousedown', 'mouseup', 'mousemove', 'click',
  'dblclick', 'wheel', 'touchstart', 'touchend', 'touchmove', 'keydown', 'keyup'] as const;

let openDialog: { close: () => void } | null = null;

function element<K extends keyof HTMLElementTagNameMap>(tag: K, text?: string, className?: string): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

function section(heading: string, ...content: HTMLElement[]): HTMLElement {
  const node = element('section');
  node.append(element('h3', heading), ...content);
  return node;
}

function entryList(entries: readonly CreditsEntry[]): HTMLUListElement {
  const list = element('ul');
  for (const entry of entries) {
    const item = element('li');
    item.append(element('strong', entry.name), element('span', t(entry.detailKey)));
    list.append(item);
  }
  return list;
}

function externalLink(text: string, href: string): HTMLAnchorElement {
  const link = element('a', text, 'credits-link');
  link.href = href;
  link.target = '_blank';
  link.rel = 'noopener';
  return link;
}

/** CC-style attribution: "Title" by Author (Freesound) · License · modified. */
function soundSection(): HTMLElement {
  const list = element('ul');
  for (const credit of SOUND_CREDITS) {
    const item = element('li');
    const title = element('strong');
    title.append(externalLink(t('ui.credits.sounds.title', { title: credit.title }), credit.sourceUrl));
    const detail = element('span', `${t('ui.credits.sounds.author', { author: credit.author })} · `);
    detail.append(externalLink(credit.license.name, credit.license.url));
    if (credit.modified) detail.append(` · ${t('ui.credits.sounds.modified')}`);
    item.append(title, detail);
    list.append(item);
  }
  return section(t('ui.credits.sounds.heading'), element('p', t('ui.credits.sounds.body')), list);
}

function noticesSection(scene: Phaser.Scene): HTMLElement {
  const toggle = element('button', t('ui.credits.licenses.show'), 'credits-notices-toggle');
  toggle.type = 'button';
  toggle.setAttribute('aria-expanded', 'false');
  const status = element('p', '', 'credits-muted');
  status.setAttribute('role', 'status');
  status.hidden = true;
  const notices = element('pre');
  notices.id = 'credits-third-party-notices';
  notices.tabIndex = 0;
  notices.hidden = true;
  toggle.setAttribute('aria-controls', notices.id);
  let request: Promise<void> | null = null;

  const load = (): Promise<void> => request ??= (async () => {
    status.hidden = false;
    status.textContent = t('ui.credits.licenses.loading');
    try {
      const response = await fetch(THIRD_PARTY_NOTICES_URL, { cache: 'no-cache' });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      notices.textContent = await response.text();
      status.hidden = true;
    } catch (error) {
      console.warn('[Credits] Third-party notices unavailable', error);
      status.textContent = t('ui.credits.licenses.failed');
      request = null;
    }
  })();

  toggle.onclick = () => activateUi(scene, () => {
    const expand = notices.hidden;
    toggle.textContent = t(expand ? 'ui.credits.licenses.hide' : 'ui.credits.licenses.show');
    toggle.setAttribute('aria-expanded', String(expand));
    if (!expand) { notices.hidden = true; status.hidden = true; return; }
    void load().then(() => { if (toggle.getAttribute('aria-expanded') === 'true') notices.hidden = !notices.textContent; });
  });
  return section(t('ui.credits.licenses.heading'), element('p', t('ui.credits.licenses.body')), toggle, status, notices);
}

/** Link to the demo's privacy page; Steam builds have no such page next to index.html. */
function privacyLink(): HTMLElement[] {
  if (__DISTRIBUTION__ !== 'web') return [];
  const link = externalLink(t('ui.credits.privacy'), PRIVACY_URL);
  const paragraph = element('p');
  paragraph.append(link);
  return [paragraph];
}

/**
 * Opens the credits as a native modal dialog above the canvas. Loaded on demand from the options
 * overlay, so neither this module nor its stylesheet are part of the boot path.
 */
export function openCreditsDialog(scene: Phaser.Scene): void {
  if (openDialog) return;
  const dialog = element('dialog', undefined, 'player-profile credits-dialog');
  dialog.setAttribute('aria-labelledby', 'credits-title');
  applyForestDialogTheme(scene, dialog, FRAME_W, FRAME_H);

  const title = element('h2', t('ui.credits.title'));
  title.id = 'credits-title';
  const body = element('div', undefined, 'credits-body');
  body.tabIndex = 0;
  body.append(
    section(t('ui.credits.game.heading'),
      element('p', t('ui.credits.game.developer', { developer: CREDITS_DEVELOPER })),
      element('p', t('ui.credits.game.version', { version: __GAME_VERSION__ }), 'credits-muted'),
      ...privacyLink()),
    section(t('ui.credits.tools.heading'), entryList(CREDITS_TOOLS)),
    section(t('ui.credits.fonts.heading'), entryList(CREDITS_FONTS)),
    soundSection(),
    section(t('ui.credits.ai.heading'), element('p', t('ui.credits.ai.body'))),
    noticesSection(scene),
  );
  dialog.append(title, body);

  const inputEnabled = scene.input.enabled;
  scene.input.enabled = false;
  for (const type of ISOLATED_EVENTS) dialog.addEventListener(type, event => event.stopPropagation());

  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    if (openDialog?.close === close) openDialog = null;
    scene.events.off('shutdown', close);
    dialog.close();
    dialog.remove();
    // Releases may have happened inside the DOM dialog; do not keep a held game pointer.
    scene.input.activePointer?.reset();
    scene.input.enabled = inputEnabled;
  };
  openDialog = { close };
  scene.events.once('shutdown', close);
  const closeButton = appendForestDialogClose(scene, dialog, FRAME_W, FRAME_H, close);
  dialog.addEventListener('cancel', event => { event.preventDefault(); close(); });

  getOverlayRoot().appendChild(dialog);
  dialog.showModal();
  closeButton.focus();
}
