/**
 * Fixed credits facts. Names of products, fonts and people are not translated; every sentence
 * around them lives in the i18n catalogs under `ui.credits.*`.
 */

/**
 * Served next to index.html; generated by scripts/generate-third-party-notices.mjs. Each distribution
 * ships its own file under this name.
 */
export const THIRD_PARTY_NOTICES_URL = './THIRD_PARTY_NOTICES.txt';

/**
 * Privacy page of the browser demo. Only the demo repository carries it
 * (scripts/deploy/demo-repo/, copied by scripts/deploy-pages.mjs), so only web builds link it.
 */
export const PRIVACY_URL = './datenschutz.html';

export const CREDITS_DEVELOPER = 'NeMe';

export interface CreditsEntry {
  readonly name: string;
  /** Translation key of the role or license line shown below the name. */
  readonly detailKey: string;
}

const WEB_CREDITS_TOOLS: readonly CreditsEntry[] = [
  { name: 'Phaser', detailKey: 'ui.credits.tools.phaser' },
  { name: 'PeerJS', detailKey: 'ui.credits.tools.peerjs' },
  { name: 'valibot', detailKey: 'ui.credits.tools.valibot' },
];

/** The steam build ships the desktop shell and Steamworks instead of the PeerJS transport. */
const STEAM_CREDITS_TOOLS: readonly CreditsEntry[] = [
  { name: 'Phaser', detailKey: 'ui.credits.tools.phaser' },
  { name: 'Electron', detailKey: 'ui.credits.tools.electron' },
  { name: 'steamworks.js', detailKey: 'ui.credits.tools.steamworksJs' },
  { name: 'Steamworks SDK', detailKey: 'ui.credits.tools.steamworksSdk' },
  { name: 'valibot', detailKey: 'ui.credits.tools.valibot' },
];

export function creditsToolsFor(distribution: typeof __DISTRIBUTION__): readonly CreditsEntry[] {
  return distribution === 'steam' ? STEAM_CREDITS_TOOLS : WEB_CREDITS_TOOLS;
}

/** Selected by the build define, so each bundle carries only the list of its own distribution. */
export const CREDITS_TOOLS = __DISTRIBUTION__ === 'steam' ? STEAM_CREDITS_TOOLS : WEB_CREDITS_TOOLS;

export const CREDITS_FONTS: readonly CreditsEntry[] = [
  { name: 'Chakra Petch', detailKey: 'ui.credits.fonts.ofl' },
  { name: 'JetBrains Mono', detailKey: 'ui.credits.fonts.ofl' },
];

/** The fixed keys plus each detail key of the given lists once. */
function withDetailKeys(fixed: readonly string[], ...lists: readonly (readonly CreditsEntry[])[]): readonly string[] {
  return [...fixed, ...new Set(lists.flat().map(entry => entry.detailKey))];
}

/**
 * Every translation key the credits dialog renders in any distribution; the catalogs must provide all
 * of them. A pure call, so a bundle that never reads it drops it with the other distribution's list.
 */
export const CREDITS_TRANSLATION_KEYS = /* @__PURE__ */ withDetailKeys([
  'ui.options.credits',
  'ui.credits.title',
  'ui.credits.game.heading',
  'ui.credits.game.developer',
  'ui.credits.game.version',
  'ui.credits.tools.heading',
  'ui.credits.fonts.heading',
  'ui.credits.sounds.heading',
  'ui.credits.sounds.body',
  'ui.credits.sounds.title',
  'ui.credits.sounds.author',
  'ui.credits.sounds.modified',
  'ui.credits.ai.heading',
  'ui.credits.ai.body',
  'ui.credits.licenses.heading',
  'ui.credits.licenses.body',
  'ui.credits.licenses.show',
  'ui.credits.licenses.hide',
  'ui.credits.licenses.loading',
  'ui.credits.licenses.failed',
  'ui.credits.privacy',
], WEB_CREDITS_TOOLS, STEAM_CREDITS_TOOLS, CREDITS_FONTS);
