/**
 * Attribution for every shipped third-party sound whose license requires it (CC BY, CC BY-NC,
 * Sampling+). Source of truth for the in-game credits; provenance details and replacement
 * decisions live in docs/legal/sound-herkunft-checkliste.md.
 *
 * Titles and author names are the original Freesound values and are never translated. When a file
 * is replaced or removed in Audio Studio, its name must leave `files`; an entry without files goes.
 */

export interface SoundLicense {
  readonly name: string;
  readonly url: string;
}

export interface SoundCredit {
  /** Shipped file names in public/assets/sounds/, including byte-identical copies of the work. */
  readonly files: readonly string[];
  readonly title: string;
  readonly author: string;
  readonly sourceUrl: string;
  readonly license: SoundLicense;
  /** All legacy imports were trimmed and converted to OGG. */
  readonly modified: boolean;
}

